79	/****************************************************************************
80	 * Private Functions - Register Access Helpers
81	 ****************************************************************************/
82	
83	static inline uint32_t getreg32(uintptr_t addr)
84	{
85	  return *(volatile uint32_t *)addr;
86	}
87	
88	static inline void putreg32(uint32_t val, uintptr_t addr)
89	{
90	  *(volatile uint32_t *)addr = val;
91	}
92	
93	static void reset_assert(unsigned int id)
94	{
95	  unsigned int bank = id / 32;
96	  unsigned int bit = id % 32;
97	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
98	
99	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
100	}
101	
102	static void reset_deassert(unsigned int id)
103	{
104	  unsigned int bank = id / 32;
105	  unsigned int bit = id % 32;
106	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
107	
108	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
109	}
110	
111	static void clk_reset_deassert(unsigned int id)
112	{
113	  unsigned int bank = id / 32;
114	  unsigned int bit = id % 32;
115	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
116	  uint32_t reg = getreg32(addr);
117	
118	  putreg32(reg | (1u << bit), addr);
119	}
