343	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
344	{
345	  uint32_t apb_id1;
346	  uint32_t apb_id2;
347	
348	  ephy_led_pinmux();
349	
350	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
351	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
352	   * This ONLY releases resets and programs the PHY ID — it does NOT
353	   * run the full analog tuning sequence.  The full tuning (which
354	   * accesses internal pages and starts auto-negotiation) must run
355	   * AFTER the MDIO interface is confirmed operational, just as
356	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
357	   */
358	
359	  /* Select APB interface to access EPHY registers */
360	
361	  putreg32(0x0001, phy_top + 0x4);
362	
363	  /* Release shutdown */
364	
365	  putreg32(0x0900, phy_top);
366	
367	  /* Release dig_rst_n — enables MII register access via APB */
368	
369	  putreg32(0x0904, phy_top);
370	
371	  /* Switch to Page 5 for ANA init */
372	
373	  putreg32(0x0500, phy_base + 0x7c);
374	
375	  /* ANA_PD (power-down release) */
376	
377	  putreg32(0x0c00, phy_base + 0x40);
378	
379	  /* ANA_EN */
380	
381	  putreg32(0x0c7e, phy_base + 0x40);
382	  up_mdelay(1);
383	
384	  /* Release ana_rst_n */
385	
386	  putreg32(0x0906, phy_top);
387	  putreg32(0x0500, phy_base + 0x7c);
388	
389	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
390	
391	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
392	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
393	
394	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
395	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
396	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
397	         "%04" PRIX32 "\n", apb_id1, apb_id2);
398	
399	  /* Switch control to MDIO (GMAC) so the DWMAC1000 MDIO controller can
400	   * discover and communicate with the PHY.
401	   */
402	
403	  putreg32(0x0000, phy_top + 0x4);
404	  up_mdelay(10);
405	
406	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
407	         " sel=0x%08" PRIX32 "\n",
408	         getreg32(phy_top), getreg32(phy_top + 0x4));
409	}
