411	/****************************************************************************
412	 * Name: ephy_full_tuning
413	 *
414	 * Description:
415	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
416	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
417	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
418	 *   internal pages and starts auto-negotiation which can interfere with
419	 *   MDIO if run before the MDIO interface is active.
420	 *
421	 ****************************************************************************/
422	
423	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
424	{
425	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
426	   * before we switch to APB for tuning.
427	   */
428	
429	  putreg32(0x0001, phy_top + 0x4);
430	  ephy_full_analog_init(phy_base, phy_top);
431	
432	  /* ephy_full_analog_init ends with:
433	   *   page 0 + autoneg start (0x090e) + force full-duplex
434	   * Switch control back to MDIO so the GMAC can manage the PHY.
435	   */
436	
437	  putreg32(0x0000, phy_top + 0x4);
438	  up_mdelay(10);
439	
440	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
441	         " sel=0x%08" PRIX32 "\n",
442	         getreg32(phy_top), getreg32(phy_top + 0x4));
443	}
444	
445	/* SG2000/CV181x uses the DWMAC1000 MDIO layout at offsets 0x10/0x14
446	 * (GMAC_MII_ADDR / GMAC_MII_DATA registers of the GMAC core).
447	 */
448	
449	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
450	{
451	  uint32_t cmd;
452	  int timeout = 10000;
453	
454	  do
455	    {
456	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
457	            GMAC_MII_BUSY))
458	        {
459	          break;
460	        }
461	
462	      up_udelay(1);
463	    }
464	  while (--timeout > 0);
465	
466	  if (timeout <= 0)
467	    {
468	      return 0xffff;
469	    }
470	
471	  putreg32(0, gmac_base + GMAC_MII_DATA);
472	
473	  cmd = (((uint32_t)phy_addr & 0x1f) << GMAC_MII_PHY_SHIFT) |
474	        (((uint32_t)reg & 0x1f) << GMAC_MII_REG_SHIFT) |
475	        GMAC_MII_CR_250_300M | GMAC_MII_BUSY;
476	  putreg32(cmd, gmac_base + GMAC_MII_ADDR);
477	
478	  timeout = 10000;
479	  do
480	    {
481	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
482	            GMAC_MII_BUSY))
483	        {
484	          return getreg32(gmac_base + GMAC_MII_DATA) & 0xffff;
485	        }
486	
487	      up_udelay(1);
488	    }
489	  while (--timeout > 0);
490	
491	  return 0xffff;
492	}
493	
494	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
495	                       uint16_t data)
496	{
497	  uint32_t cmd;
498	  int timeout = 10000;
499	
500	  putreg32(data, gmac_base + GMAC_MII_DATA);
501	  cmd = (((uint32_t)phy_addr & 0x1f) << GMAC_MII_PHY_SHIFT) |
502	        (((uint32_t)reg & 0x1f) << GMAC_MII_REG_SHIFT) |
503	        GMAC_MII_CR_250_300M | GMAC_MII_WRITE |
504	        GMAC_MII_BUSY;
505	  putreg32(cmd, gmac_base + GMAC_MII_ADDR);
506	
507	  do
508	    {
509	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
510	            GMAC_MII_BUSY))
511	        {
512	          break;
513	        }
514	
515	      up_udelay(1);
516	    }
517	  while (--timeout > 0);
518	}
