520	static int mdio_verify_phy(uintptr_t gmac_base)
521	{
522	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
523	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
524	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
525	
526	  syslog(LOG_INFO, "sg2000_eth: MDIO probe phy_id=0x%08"
527	         PRIX32 "\n", phy_id);
528	
529	  if (id1 == 0xffff || id2 == 0xffff)
530	    {
531	      syslog(LOG_ERR, "sg2000_eth: MDIO timeout reading "
532	             "PHY ID\n");
533	      return -ENODEV;
534	    }
535	
536	  if (phy_id != CVITEK_PHY_ID)
537	    {
538	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
539	             " (expected 0x%08" PRIX32 ")\n", phy_id,
540	             (uint32_t)CVITEK_PHY_ID);
541	    }
542	
543	  return OK;
544	}
