548	 ****************************************************************************/
549	
550	static int phy_config_init(struct sg2000_eth_priv_s *priv)
551	{
552	  uint16_t bmsr;
553	  uint16_t bmcr;
554	  uint16_t anlpar;
555	  int timeout;
556	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
557	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
558	  uint32_t phy_id = (id1 << 16) | id2;
559	
560	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
561	         " expect=0x00435649\n", phy_id);
562	
563	  if (phy_id == 0xffffffff)
564	    {
565	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
566	      return -1;
567	    }
568	
569	  if (phy_id != CVITEK_PHY_ID)
570	    {
571	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
572	             "\n", phy_id);
573	    }
574	
575	  priv->speed = 100;
576	  priv->duplex = 1;
577	
578	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
579	  up_mdelay(10);
580	
581	  timeout = 100;
582	  do
583	    {
584	      bmcr = mdio_read(priv->gmac_base, 0, 0);
585	      if (!(bmcr & 0x8000))
586	        {
587	          break;
588	        }
589	
590	      up_mdelay(1);
591	    }
592	  while (--timeout > 0);
593	
594	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
595	
596	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
597	
598	  bmcr = mdio_read(priv->gmac_base, 0, 0);
599	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
600	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
601	         bmcr | 0x1200);
602	
603	  timeout = 50;
604	  do
605	    {
606	      (void)mdio_read(priv->gmac_base, 0, 1);
607	      bmsr = mdio_read(priv->gmac_base, 0, 1);
608	      if ((bmsr & 0x0004) != 0)
609	        {
610	          break;
611	        }
612	
613	      up_mdelay(100);
614	    }
615	  while (--timeout > 0);
616	
617	  if ((bmsr & 0x0004) == 0)
618	    {
619	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
620	             bmsr);
621	      priv->link_up = 0;
622	      return OK;
623	    }
624	
625	  anlpar = mdio_read(priv->gmac_base, 0, 5);
626	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
627	         "ANLPAR=0x%04X\n", bmsr, anlpar);
628	
629	  if ((anlpar & 0x0100) != 0)
630	    {
631	      priv->speed = 100;
632	      priv->duplex = 1;
633	    }
634	  else if ((anlpar & 0x0080) != 0)
635	    {
636	      priv->speed = 100;
637	      priv->duplex = 0;
638	    }
639	  else if ((anlpar & 0x0040) != 0)
640	    {
641	      priv->speed = 10;
642	      priv->duplex = 1;
643	    }
644	  else
645	    {
646	      priv->speed = 10;
647	      priv->duplex = 0;
648	    }
649	
650	  priv->link_up = 1;
651	
652	  return 0;
653	}
