655	/****************************************************************************
656	 * Private Functions - DMA Descriptor Management
657	 ****************************************************************************/
658	
659	static int alloc_dma(struct sg2000_eth_priv_s *priv)
660	{
661	  int i;
662	
663	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
664	                                sizeof(struct sg2000_dma_desc_s));
665	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
666	                                sizeof(struct sg2000_dma_desc_s));
667	
668	  if (!priv->tx_desc || !priv->rx_desc)
669	    {
670	      return -ENOMEM;
671	    }
672	
673	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
674	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	
676	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
677	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
678	   */
679	
680	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
681	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
682	
683	  for (i = 0; i < TX_RING_SIZE; i++)
684	    {
685	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
686	      if (!priv->tx_buf[i])
687	        {
688	          return -ENOMEM;
689	        }
690	
691	      priv->tx_pkt[i] = NULL;
692	    }
693	
694	  for (i = 0; i < RX_RING_SIZE; i++)
695	    {
696	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
697	      if (!priv->rx_buf[i])
698	        {
699	          return -ENOMEM;
700	        }
701	    }
702	
703	  return 0;
704	}
705	
706	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
707	{
708	  uintptr_t base = priv->gmac_base;
709	  int i;
710	
711	  /* Initialize TX descriptors.
712	   * Mark the last descriptor with END_RING so DMA knows the ring boundary.
713	   */
714	
715	  for (i = 0; i < TX_RING_SIZE; i++)
716	    {
717	      priv->tx_desc[i].des0 = 0;
718	      priv->tx_desc[i].des1 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
719	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
720	      priv->tx_desc[i].des3 = 0;
721	      priv->tx_pkt[i] = NULL;
722	    }
723	
724	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
725	   * Mark the last descriptor with RER (RX End of Ring) in des1.
726	   */
727	
728	  for (i = 0; i < RX_RING_SIZE; i++)
729	    {
730	      priv->rx_desc[i].des0 = DESC_OWN;
731	      priv->rx_desc[i].des1 = RX_BUF_SIZE |
732	                              ((i == RX_RING_SIZE - 1) ? RX_DESC_RER : 0);
733	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
734	      priv->rx_desc[i].des3 = 0;
735	    }
736	
737	  priv->tx_cur = 0;
738	  priv->tx_dirty = 0;
739	  priv->rx_cur = 0;
740	
741	  /* Verify descriptor size compatibility before configuring DMA Bus Mode.
742	   *
743	   * ATDS=0 uses normal 16-byte descriptors (OWN in TDES0, control bits
744	   * FS/LS/IC/TER in TDES1).  The descriptor size is always 16 bytes
745	   * regardless of the timestamp engine state, so the 32-byte extended
746	   * descriptor problem does not apply here.
747	   *
748	   * We still log HW_FEATURE for diagnostics and explicitly disable the
749	   * timestamp engine if present (timestamp is not used by this driver).
750	   */
751	  {
752	    uint32_t hw_feat = getreg32(base + DMA_HW_FEATURE);
753	
754	    syslog(LOG_INFO,
755	           "sg2000_eth: DMA_HW_FEATURE=0x%08" PRIX32 "\n", hw_feat);
756	
757	    if (hw_feat & DMA_HW_FEATURE_TSEN)
758	      {
759	        /* Timestamp engine is present — not needed, keep it off. */
760	
761	        uint32_t ts_ctrl = getreg32(base + GMAC_TIMESTAMP_CTRL);
762	
763	        if (ts_ctrl & GMAC_TS_TSENA)
764	          {
765	            putreg32(ts_ctrl & ~GMAC_TS_TSENA,
766	                     base + GMAC_TIMESTAMP_CTRL);
767	            syslog(LOG_WARNING,
768	                   "sg2000_eth: timestamp was enabled; "
769	                   "disabled (not used)\n");
770	          }
771	
772	        syslog(LOG_INFO,
773	               "sg2000_eth: timestamp HW present, TSENA=0, "
774	               "ATDS=0 (16-byte normal desc)\n");
775	      }
776	    else
777	      {
778	        syslog(LOG_INFO,
779	               "sg2000_eth: no timestamp HW, "
780	               "ATDS=0 (16-byte normal desc)\n");
781	      }
782	  }
783	
784	  /* Configure DMA Bus Mode (CSR0): Fixed Burst, AAL, USP, PBL=8 (ATDS=0) */
785	  putreg32(DMA_BUS_DEFAULT, base + DMA_BUS_MODE);
786	
787	  /* Configure AXI Bus Mode (CSR10): burst lengths + OSR limits */
788	  putreg32(DMA_AXI_DEFAULT, base + DMA_AXI_BUS_MODE);
789	
790	  /* Write descriptor ring base addresses */
791	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
792	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
793	
794	  /* Mask all DMA interrupts via CSR7 (they are unmasked in start_mac_and_dma) */
795	  putreg32(0, base + DMA_INTR_ENA);
796	}
797	
798	/****************************************************************************
799	 * Private Functions - MAC and DMA Control
800	 ****************************************************************************/
801	
802	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
803	{
804	  uint32_t hi;
805	  uint32_t lo;
806	
807	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
808	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
809	
810	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
811	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
812	}
813	
814	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
815	{
816	  uintptr_t gmac_base = priv->gmac_base;
817	  uint32_t v;
818	
819	  /* Configure MAC based on PHY negotiation results */
820	
821	  v = GMAC_CORE_INIT;
822	  if (priv->speed == 100)
823	    {
824	      v |= GMAC_CONFIG_FES;   /* 100M */
825	    }
826	
827	  if (priv->duplex)
828	    {
829	      v |= GMAC_CONFIG_DM;    /* Full duplex */
830	    }
831	
832	  /* Enable MAC TX and RX */
833	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
834	
835	  putreg32(v, gmac_base + GMAC_CONFIG);
836	
837	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
838	   * Pass multicast + broadcast + unicast (promiscuous mode).
839	   */
840	
841	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
842	           gmac_base + GMAC_FRAME_FILTER);
843	
844	  /* Enable MAC interrupts */
845	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
846	
847	  /* Enable DMA interrupts via CSR7 */
848	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
849	
850	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
851	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
852	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
853	   */
854	
855	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
856	           DMA_CONTROL_ST | DMA_CONTROL_SR,
857	           gmac_base + DMA_CONTROL);
858	}
859	
860	/****************************************************************************
861	 * Private Functions - Doorbell Helpers
862	 ****************************************************************************/
863	
864	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
865	{
866	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
867	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
868	   */
869	
870	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
871	}
872	
873	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
874	{
875	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
876	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
877	   */
878	
879	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
880	}
