882	/****************************************************************************
883	 * Private Functions - Hardware Transmit
884	 ****************************************************************************/
885	
886	static int hw_transmit(struct sg2000_eth_priv_s *priv,
887	                       const uint8_t *data, int len)
888	{
889	  unsigned int idx = priv->tx_cur;
890	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
891	  irqstate_t flags;
892	  uint32_t csr5_before;
893	  uint32_t csr6;
894	
895	  /* Check if the ring is full */
896	
897	  if (desc->des0 & DESC_OWN)
898	    {
899	      return -EBUSY;
900	    }
901	
902	  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */
903	
904	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
905	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
906	
907	  /* Copy data to DMA TX buffer */
908	
909	  memcpy(priv->tx_buf[idx], data, len);
910	
911	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
912	
913	  /* Set OWN on des0.  FS | LS | IC | len on des1.
914	   * Preserve TER (END_RING) bit in des1 if it was set during init.
915	   */
916	
917	  desc->des1 = (uint32_t)len | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
918	               (desc->des1 & TX_DESC_TER);
919	  desc->des0 = DESC_OWN;
920	
921	  /* Diagnostic: dump first 50 bytes of TX buffer (pointed to by des2).
922	   * Note: des1 is a control/status field (len | FS | LS | IC | TER),
923	   * NOT a buffer pointer.  The actual data buffer address is in des2.
924	   */
925	
926	  {
927	    int i;
928	    int dump_len = len < 50 ? len : 50;
929	
930	    syslog(LOG_INFO,
931	           "sg2000_eth: TX data[%u] des2=0x%08" PRIX32
932	           " first %d bytes:",
933	           idx, desc->des2, dump_len);
934	
935	    for (i = 0; i < dump_len; i += 16)
936	      {
937	        int row = 0;
938	        char hex[64];
939	        char ascii[20];
940	        int j;
941	
942	        row += snprintf(hex + row, sizeof(hex) - row, "  %04x:", i);
943	
944	        for (j = 0; j < 16; j++)
945	          {
946	            if (i + j < dump_len)
947	              {
948	                row += snprintf(hex + row, sizeof(hex) - row,
949	                                " %02x", priv->tx_buf[idx][i + j]);
950	                ascii[j] = (priv->tx_buf[idx][i + j] >= 32 &&
951	                           priv->tx_buf[idx][i + j] < 127)
952	                           ? priv->tx_buf[idx][i + j] : '.';
953	              }
954	            else
955	              {
956	                row += snprintf(hex + row, sizeof(hex) - row, "   ");
957	                ascii[j] = ' ';
958	              }
959	          }
960	
961	        ascii[16] = '\0';
962	        syslog(LOG_INFO, "%s  |%s|\n", hex, ascii);
963	      }
964	  }
965	
966	  /* Diagnostic: dump TX descriptor and DMA state before doorbell */
967	
968	  syslog(LOG_INFO,
969	         "sg2000_eth: TX idx=%u len=%d\n"
970	         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
971	         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
972	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
973	         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
974	         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
975	         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
976	         idx, len,
977	         desc->des0, desc->des1, desc->des2, desc->des3,
978	         csr5_before, csr6,
979	         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
980	         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
981	         data[0], data[1], data[2], data[3], data[4], data[5],
982	         data[6], data[7], data[8], data[9], data[10], data[11],
983	         data[12], data[13]);
984	
985	  flags = up_irq_save();
986	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
987	
988	  /* Memory barrier: ensure descriptor is visible to DMA engine */
989	
990	  __asm__ volatile ("fence w,w" ::: "memory");
991	
992	  tx_doorbell(priv);
993	
994	  /* Verify DMA operation: poll descriptor OWN bit with timeout.
995	   * If DMA clears OWN, TX is working.  If OWN stays set, DMA is stuck.
996	   */
997	
998	  {
999	    int timeout = 10000;
1000	    while ((desc->des0 & DESC_OWN) && --timeout > 0)
1001	      {
1002	        up_udelay(10);
1003	      }
1004	
1005	    syslog(LOG_INFO,
1006	           "sg2000_eth: TX complete check: OWN=%s timeout=%d "
1007	           "CSR5=0x%08" PRIX32 "\n",
1008	           (desc->des0 & DESC_OWN) ? "STILL_SET(DMA_STUCK)" : "CLEARED(OK)",
1009	           10000 - timeout,
1010	           getreg32(priv->gmac_base + DMA_STATUS));
1011	  }
1012	
1013	  up_irq_restore(flags);
1014	
1015	  return 0;
1016	}
1017	
1018	/****************************************************************************
1019	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1020	 ****************************************************************************/
1021	
1022	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1023	{
1024	  irqstate_t flags = up_irq_save();
1025	
1026	  while (priv->tx_dirty != priv->tx_cur)
1027	    {
1028	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1029	
1030	      if (desc->des0 & DESC_OWN)
1031	        {
1032	          /* Still owned by DMA, stop */
1033	
1034	          break;
1035	        }
1036	
1037	      /* Free the netpkt if we have one tracked for this slot */
1038	
1039	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1040	        {
1041	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1042	          priv->tx_pkt[priv->tx_dirty] = NULL;
1043	
1044	          /* Notify upper half that TX is done */
1045	
1046	          netdev_lower_txdone(&priv->dev);
1047	        }
1048	
1049	      /* Move to next descriptor */
1050	
1051	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1052	    }
1053	
1054	  up_irq_restore(flags);
1055	}
1056	
1057	/****************************************************************************
1058	 * Private Functions - ISR
1059	 ****************************************************************************/
1060	
1061	static int sg2000_eth_isr(int irq, void *context, void *arg)
1062	{
1063	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1064	  uintptr_t base = priv->gmac_base;
1065	  uint32_t status;
1066	  uint32_t mac;
1067	
1068	  /* Clear MAC interrupts */
1069	
1070	  mac = getreg32(base + GMAC_INT_STATUS);
1071	  if (mac)
1072	    {
1073	      putreg32(mac, base + GMAC_INT_STATUS);
1074	    }
1075	
1076	  /* Read DMA Status (CSR5 at 0x1014) */
1077	
1078	  status = getreg32(base + DMA_STATUS);
1079	
1080	  if (!status)
1081	    {
1082	      return OK;
1083	    }
1084	
1085	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
1086	
1087	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1088	
1089	  if (status & DMA_STATUS_NIS)
1090	    {
1091	      /* Normal interrupt */
1092	
1093	      if (status & DMA_STATUS_RI)
1094	        {
1095	          /* RX complete: notify upper half */
1096	          netdev_lower_rxready(&priv->dev);
1097	        }
1098	
1099	      if (status & DMA_STATUS_TI)
1100	        {
1101	          /* TX complete: cleanup descriptors */
1102	          tx_cleanup(priv);
1103	        }
1104	    }
1105	
1106	  if (status & DMA_STATUS_AIS)
1107	    {
1108	      /* Abnormal interrupt - handled silently in ISR context */
1109	    }
1110	
1111	  return OK;
1112	}
