1114	/****************************************************************************
1115	 * Name: netdriver_ifup
1116	 *
1117	 * Description:
1118	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1119	 *
1120	 ****************************************************************************/
1121	
1122	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1123	{
1124	  FAR struct sg2000_eth_priv_s *priv =
1125	      (FAR struct sg2000_eth_priv_s *)dev;
1126	  int ret;
1127	
1128	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1129	
1130	  /* Ensure GMAC clocks and resets are configured */
1131	
1132	  gmac_clock_enable();
1133	
1134	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1135	
1136	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1137	
1138	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1139	  up_mdelay(10);
1140	
1141	  ret = mdio_verify_phy(priv->gmac_base);
1142	  if (ret < 0)
1143	    {
1144	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1145	      return ret;
1146	    }
1147	
1148	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1149	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1150	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1151	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1152	
1153	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1154	
1155	  ret = phy_config_init(priv);
1156	  if (ret < 0)
1157	    {
1158	      nerr("ERROR: PHY init failed: %d\n", ret);
1159	      return ret;
1160	    }
1161	
1162	  ret = dma_soft_reset(priv->gmac_base);
1163	  if (ret < 0)
1164	    {
1165	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1166	             "diagnostics: %d\n", ret);
1167	      return ret;
1168	    }
1169	
1170	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1171	    {
1172	      ret = alloc_dma(priv);
1173	      if (ret < 0)
1174	        {
1175	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1176	          return ret;
1177	        }
1178	    }
1179	
