1187	   */
1188	
1189	  {
1190	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1191	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1192	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1193	    unsigned int rx_state = (csr5 >> 17) & 0x7;
