1196	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1197	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1198	    };
1199	
1200	    syslog(LOG_INFO,
1201	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1202	           " CSR6=0x%08" PRIX32 "\n"
1203	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1204	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1205	           csr5, csr6,
