1221	 * Name: netdriver_ifdown
1222	 *
1223	 * Description:
1224	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1225	 *
1226	 ****************************************************************************/
1227	
1228	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1229	{
1230	  FAR struct sg2000_eth_priv_s *priv =
1231	      (FAR struct sg2000_eth_priv_s *)dev;
1232	  uint32_t v;
1233	
1234	  up_disable_irq(priv->irq);
1235	
1236	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1237	   * Clear ST (bit 13) and SR (bit 1).
1238	   */
1239	
1240	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1241	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1242	           priv->gmac_base + DMA_CONTROL);
1243	
1244	  /* Disable MAC TX/RX */
1245	
1246	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1247	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1248	           priv->gmac_base + GMAC_CONFIG);
1249	
1250	  netdev_lower_carrier_off(dev);
1251	
1252	  ninfo("netdriver_ifdown: interface down\n");
