1257	/****************************************************************************
1258	 * Name: netdriver_transmit
1259	 *
1260	 * Description:
1261	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1262	 *   The driver takes ownership of the netpkt and MUST free it after TX
1263	 *   completion (or on error).
1264	 *
1265	 *   Returned Value:
1266	 *     OK on success (pkt queued for TX); negated errno on failure.
1267	 *
1268	 ****************************************************************************/
1269	
1270	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1271	                               FAR netpkt_t *pkt)
1272	{
1273	  FAR struct sg2000_eth_priv_s *priv =
1274	      (FAR struct sg2000_eth_priv_s *)dev;
1275	  unsigned int len = netpkt_getdatalen(dev, pkt);
1276	  uint8_t *tmp_buf = NULL;
1277	  const uint8_t *data;
1278	  int ret;
1279	
1280	  if (len > SG2000_ETH_BUFSIZE)
1281	    {
1282	      nerr("ERROR: TX packet too large: %u\n", len);
1283	      netpkt_free(dev, pkt, NETPKT_TX);
1284	      return -E2BIG;
1285	    }
1286	
1287	  /* Extract data from netpkt.  If fragmented, copy out to a heap buffer;
1288	   * otherwise use the IOB data pointer directly.
1289	   *
1290	   * A heap buffer is used instead of a stack buffer because
1291	   * SG2000_ETH_BUFSIZE (1600 bytes) risks stack overflow on the
1292	   * netdev thread which has a limited stack size.
1293	   */
1294	
1295	  if (netpkt_is_fragmented(pkt))
1296	    {
1297	      tmp_buf = kmm_malloc(SG2000_ETH_BUFSIZE);
1298	      if (!tmp_buf)
1299	        {
1300	          nerr("ERROR: kmm_malloc(%u) for TX copy buffer failed\n",
1301	               SG2000_ETH_BUFSIZE);
1302	          netpkt_free(dev, pkt, NETPKT_TX);
1303	          return -ENOMEM;
1304	        }
1305	
1306	      syslog(LOG_INFO,
1307	             "sg2000_eth: TX fragmented pkt, len=%u, "
1308	             "copied to heap buf=%p\n", len, tmp_buf);
1309	
1310	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1311	      data = tmp_buf;
1312	    }
1313	  else
1314	    {
1315	      data = netpkt_getdata(dev, pkt);
1316	      if (!data)
1317	        {
1318	          nerr("ERROR: netpkt_getdata returned NULL\n");
1319	          netpkt_free(dev, pkt, NETPKT_TX);
1320	          return -EINVAL;
1321	        }
1322	    }
1323	
1324	  /* Send via DMA */
1325	
1326	  ret = hw_transmit(priv, data, len);
1327	
1328	  /* Free the temporary copy buffer if it was allocated.
1329	   * Safe to free here: hw_transmit() already memcpy'd data into the
1330	   * DMA TX buffer and waited for DMA completion before returning.
1331	   */
1332	
1333	  if (tmp_buf)
1334	    {
1335	      kmm_free(tmp_buf);
1336	    }
1337	
1338	  if (ret < 0)
1339	    {
1340	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1341	      netpkt_free(dev, pkt, NETPKT_TX);
1342	      return ret;
1343	    }
1344	
1345	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1346	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1347	   */
1348	
1349	  {
1350	    irqstate_t flags = up_irq_save();
1351	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1352	
1353	    priv->tx_pkt[slot] = pkt;
1354	    up_irq_restore(flags);
1355	  }
1356	
1357	  return OK;
1358	}
