1360	/****************************************************************************
1361	 * Name: netdriver_receive
1362	 *
1363	 * Description:
1364	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1365	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1366	 *   NULL if no more packets are available.
1367	 *
1368	 *   Returned Value:
1369	 *     A netpkt_t * containing the received packet, or NULL.
1370	 *
1371	 ****************************************************************************/
1372	
1373	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1374	{
1375	  FAR struct sg2000_eth_priv_s *priv =
1376	      (FAR struct sg2000_eth_priv_s *)dev;
1377	  FAR netpkt_t *pkt = NULL;
1378	  struct sg2000_dma_desc_s *desc;
1379	  uint32_t status;
1380	  int frame_len;
1381	  int ret;
1382	
1383	  /* Check if there is a completed RX descriptor */
1384	
1385	  desc = &priv->rx_desc[priv->rx_cur];
1386	  if (desc->des0 & DESC_OWN)
1387	    {
1388	      /* DMA still owns it, no packet ready yet.
1389	       * This can happen if rxready was signaled for a previous packet
1390	       * that was already consumed, or in edge cases.
1391	       */
1392	
1393	      return NULL;
1394	    }
1395	
1396	  status = desc->des0;
1397	
1398	  /* Check for errors */
1399	
1400	  if (status & RX_DESC_ES)
1401	    {
1402	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1403	      goto refill;
1404	    }
1405	
1406	  /* Get frame length.  GMAC_CONFIG_ACS is set, so the hardware
1407	   * already strips the FCS; the length from the descriptor is the
1408	   * actual frame length without CRC.
1409	   */
1410	
1411	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK);
1412	
1413	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1414	    {
1415	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1416	      goto refill;
1417	    }
1418	
1419	  /* Allocate a netpkt for the received data */
1420	
1421	  pkt = netpkt_alloc(dev, NETPKT_RX);
1422	  if (!pkt)
1423	    {
1424	      nerr("ERROR: netpkt_alloc failed\n");
1425	      goto refill;
1426	    }
1427	
1428	  /* Copy data from DMA RX buffer into the netpkt */
1429	
1430	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1431	  if (ret < 0)
1432	    {
1433	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1434	      netpkt_free(dev, pkt, NETPKT_RX);
1435	      goto refill;
1436	    }
1437	
1438	refill:
1439	  /* Return the descriptor to DMA (set OWN=1).
1440	   * Preserve RER (RX End of Ring) bit in des1 if set during init.
1441	   */
1442	
1443	  desc->des0 = DESC_OWN;
1444	  desc->des1 = RX_BUF_SIZE | (desc->des1 & RX_DESC_RER);
1445	
1446	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1447	  rx_doorbell(priv);
1448	
1449	  return pkt;
1450	}
