/****************************************************************************
 * Name: sg2000_eth_tx_test
 *
 * Description:
 *   Minimal hardware TX verification test.
 *   Bypasses the network stack entirely — directly programs a TX descriptor,
 *   rings the doorbell, and verifies the DMA engine can:
 *     (1) fetch the descriptor from DDR   (OWN bit cleared by DMA)
 *     (2) read the buffer data correctly  (no Underflow error)
 *     (3) generate TX Complete interrupt  (CSR5 TI bit set)
 *
 *   Prerequisite: ifup has completed successfully (PHY link up, DMA running).
 *
 ****************************************************************************/

int sg2000_eth_tx_test(void)
{
  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
  struct sg2000_dma_desc_s saved_desc;
  uint32_t csr5_before;
  uint32_t csr5_after;
  uint32_t csr6;
  int timeout;
  int test_len = 64;
  int i;
  int ret = 0;

  /* ================================================================
   * STEP 0: Pre-flight checks
   * ================================================================ */

  if (!priv->link_up)
    {
      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
      return -ENETDOWN;
    }

  if (desc->des0 & DESC_OWN)
    {
      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
      return -EBUSY;
    }

  syslog(LOG_INFO,
         "=== sg2000_eth TX hardware test ===\n"
         "  gmac_base=0x%08" PRIX32
         " tx_desc[%u]=%p (phys=0x%08" PRIX32 ")\n"
         "  tx_buf=%p test_len=%d\n",
         (uint32_t)priv->gmac_base, idx,
         desc, (uint32_t)(uintptr_t)desc,
         priv->tx_buf[idx], test_len);

  /* ================================================================
   * STEP 1: Build a minimal test Ethernet frame
   *
   *   dst: ff:ff:ff:ff:ff:ff (broadcast)
   *   src: our MAC
   *   type: 0x0806 (ARP)
   *   payload: pattern 0xAA (recognizable on wire)
   *
   * A valid frame is used so the MAC accepts it for transmission
   * without complaints.
   * ================================================================ */

  memset(priv->tx_buf[idx], 0, test_len);

  /* Destination: broadcast */

  memset(priv->tx_buf[idx], 0xff, 6);

  /* Source: our MAC */

  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);

  /* EtherType = ARP (0x0806) */

  priv->tx_buf[idx][12] = 0x08;
  priv->tx_buf[idx][13] = 0x06;

  /* Payload: fill with 0xAA pattern (easy to spot in a sniffer) */

  memset(priv->tx_buf[idx] + 14, 0xAA, test_len - 14);

  syslog(LOG_INFO, "tx_test: frame built, dst=ff:ff:ff:ff:ff:ff "
         "src=%02x:%02x:%02x:%02x:%02x:%02x type=0x%02x%02x\n",
         priv->mac_addr[0], priv->mac_addr[1], priv->mac_addr[2],
         priv->mac_addr[3], priv->mac_addr[4], priv->mac_addr[5],
         priv->tx_buf[idx][12], priv->tx_buf[idx][13]);

  /* ================================================================
   * STEP 2: Snapshot hardware state BEFORE submission
   * ================================================================ */

  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);

  /* Save descriptor for later comparison */

  saved_desc.des0 = desc->des0;
  saved_desc.des1 = desc->des1;
  saved_desc.des2 = desc->des2;
  saved_desc.des3 = desc->des3;

  syslog(LOG_INFO,
         "tx_test: BEFORE doorbell\n"
         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
         "  CSR5(TX state)=0x%08" PRIX32
         " CSR6=0x%08" PRIX32 " TX_FSM=%u\n",
         desc->des0, desc->des1, desc->des2, desc->des3,
         csr5_before, csr6, (csr5_before >> 20) & 0x7);

  /* ================================================================
   * STEP 3: Program the TX descriptor
   *
   *   des2 = buffer physical address
   *   des1 = length | FS | LS | IC  (preserve TER)
   *   des0 = OWN  (hand to DMA)
   *
   * After this, the descriptor lives in D-cache.
   * We flush it to DDR before ringing the doorbell.
   * ================================================================ */

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
  desc->des1 = (uint32_t)test_len | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
               (desc->des1 & TX_DESC_TER);
  desc->des0 = DESC_OWN;

  syslog(LOG_INFO,
         "tx_test: descriptor programmed\n"
         "  des0=0x%08" PRIX32 " (OWN set)  des1=0x%08" PRIX32 "\n"
         "  des2=0x%08" PRIX32 " (buf phys)\n",
         desc->des0, desc->des1, desc->des2);

  /* ================================================================
   * STEP 4: Flush D-cache → DDR
   *
   *   Critical: DMA reads from DDR, not from CPU cache.
   *   Without this flush, DMA may see stale (zero) descriptor values.
   *   This is the fix for the cache coherency bug identified in the
   *   driver analysis.
   * ================================================================ */

  /* Flush TX buffer (contains the frame data) */

  up_clean_dcache((uintptr_t)priv->tx_buf[idx],
                  (uintptr_t)priv->tx_buf[idx] + test_len);

  /* Flush TX descriptor (contains OWN, des1, des2) */

  up_clean_dcache((uintptr_t)desc,
                  (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));

  /* Fence: ensure flush completes before MMIO doorbell */

  __asm__ volatile ("fence ow,ow" ::: "memory");

  syslog(LOG_INFO, "tx_test: D-cache flushed to DDR\n");

  /* ================================================================
   * STEP 5: Ring the TX doorbell
   *
   *   Write to DMA_XMT_POLL_DEMAND (CSR1) to tell the TX DMA
   *   state machine to fetch the descriptor ring from DDR.
   * ================================================================ */

  syslog(LOG_INFO, "tx_test: ringing TX doorbell...\n");
  tx_doorbell(priv);

  /* ================================================================
   * STEP 6: Wait for TX completion
   *
   *   Two methods to detect completion:
   *     (a) Poll the OWN bit on the descriptor — DMA clears it when
   *         the frame has been read from memory and queued to the MAC.
   *     (b) Poll CSR5 (DMA Status) for the TI (Transmit Interrupt)
   *         bit — this confirms the TX complete interrupt fired.
   *
   *   We check both to verify the full TX interrupt path.
   * ================================================================ */

  timeout = 50000;  /* 500ms max */

  while (--timeout > 0)
    {
      /* Read CSR5 from hardware (not from cache) */

      csr5_after = getreg32(priv->gmac_base + DMA_STATUS);

      /* Check: DMA cleared OWN (descriptor consumed) AND TI bit set */

      if (!(desc->des0 & DESC_OWN) && (csr5_after & DMA_STATUS_TI))
        {
          break;
        }

      up_udelay(10);
    }

  syslog(LOG_INFO,
         "tx_test: after %d us  timeout=%s\n"
         "  CSR5=0x%08" PRIX32 " TI=%s ETI=%s\n",
         (50000 - timeout) * 10,
         timeout > 0 ? "no" : "YES",
         csr5_after,
         (csr5_after & DMA_STATUS_TI) ? "SET" : "clear",
         (csr5_after & DMA_STATUS_ETI) ? "SET" : "clear");

  /* ================================================================
   * STEP 7: Verify — layer by layer
   * ================================================================ */

  /* --- Layer 1: Did DMA fetch the descriptor? ---
   *   If DMA can read the descriptor from DDR, it sees OWN=1,
   *   claims ownership, processes the frame, then clears OWN.
   *   If OWN is still set → DMA never saw our descriptor
   *   → cache coherency problem or DMA not running.
   */

  if (desc->des0 & DESC_OWN)
    {
      syslog(LOG_ERR,
             "*** FAIL [Layer 1]: OWN still set — DMA did NOT fetch "
             "descriptor from DDR!\n"
             "  This indicates a cache coherency problem:\n"
             "  DMA reads from DDR but descriptor is stuck in D-cache.\n");

      /* Read back CSR5/CSR6 for diagnosis */

      syslog(LOG_ERR,
             "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32 "\n"
             "  TX_FSM=%u (0=Stopped, 1=FetchDesc)\n"
             "  TX_BASE=0x%08" PRIX32 "\n",
             getreg32(priv->gmac_base + DMA_STATUS),
             getreg32(priv->gmac_base + DMA_CONTROL),
             (getreg32(priv->gmac_base + DMA_STATUS) >> 20) & 0x7,
             getreg32(priv->gmac_base + DMA_TX_BASE_ADDR));
      ret = -ETIMEDOUT;
      goto out;
    }

  syslog(LOG_INFO, "  [Layer 1 PASS] DMA fetched descriptor "
         "(OWN cleared by DMA)\n");

  /* --- Layer 2: Did DMA read the data correctly? ---
   *   Check for Underflow Error (UE) in CSR5 and Error Summary
   *   in des0.  Underflow means DMA could not read data from
   *   memory fast enough — often caused by stale cache.
   */

  if (csr5_after & DMA_STATUS_UNF)
    {
      syslog(LOG_ERR,
             "*** FAIL [Layer 2]: TX Underflow! DMA could not read "
             "data from memory.\n"
             "  CSR5=0x%08" PRIX32 " (UNF bit set)\n",
             csr5_after);
      ret = -EIO;
      goto out;
    }

  if (desc->des0 & TX_DESC_ES)
    {
      syslog(LOG_ERR,
             "*** FAIL [Layer 2]: TX Error Summary set in des0.\n"
             "  des0=0x%08" PRIX32 "\n", desc->des0);
      ret = -EIO;
      goto out;
    }

  syslog(LOG_INFO, "  [Layer 2 PASS] No Underflow/Error — DMA read "
         "data correctly\n");

  /* --- Layer 3: Did TX Complete interrupt fire? ---
   *   The descriptor was configured with IC (Interrupt on Completion).
   *   If TI is set in CSR5, the interrupt path is working.
   */

  if (!(csr5_after & DMA_STATUS_TI))
    {
      syslog(LOG_ERR,
             "*** FAIL [Layer 3]: TI bit NOT set — TX Complete "
             "interrupt did not fire.\n"
             "  Check DMA_INTR_ENA (CSR7) and GMAC_INT_MASK.\n");
      ret = -EIO;
      goto out;
    }

  syslog(LOG_INFO, "  [Layer 3 PASS] TX Complete interrupt (TI) fired\n");

  /* ================================================================
   * STEP 8: Report results
   * ================================================================ */

  syslog(LOG_INFO,
         "=== TX TEST PASSED ===\n"
         "  DMA read descriptor:   OK\n"
         "  DMA read buffer data:  OK (no underflow)\n"
         "  TX Complete interrupt:  OK\n"
         "  Total time: ~%d us\n",
         (50000 - timeout) * 10);

out:
  /* Move tx_cur forward (mirror what hw_transmit does) */

  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  /* Clear TI bit so it doesn't interfere with normal operation */

  if (csr5_after & DMA_STATUS_TI)
    {
      putreg32(DMA_STATUS_TI, priv->gmac_base + DMA_STATUS);
    }

  return ret;
}
