/****************************************************************************
 * Name: sg2000_eth_tx_test
 *
 * Description:
 *   Minimal hardware TX verification test.
 *   Bypasses the network stack — directly programs a TX descriptor,
 *   rings the doorbell, and verifies the DMA engine can:
 *     Layer 1: Fetch the descriptor from DDR  (OWN bit cleared)
 *     Layer 2: Read buffer data correctly     (no Underflow)
 *     Layer 3: Generate TX Complete interrupt  (CSR5 TI bit)
 *
 *   Prerequisite: ifup has completed (PHY up, DMA running).
 *
 ****************************************************************************/

static int sg2000_eth_tx_test(void)
{
  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
  uint32_t csr5_before;
  uint32_t csr5_after;
  uint32_t csr6;
  int timeout;
  int test_len = 64;
  int ret = 0;

  /* STEP 0: Pre-flight checks */

  if (!priv->link_up)
    {
      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
      return -ENETDOWN;
    }

  if (desc->des0 & DESC_OWN)
    {
      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
      return -EBUSY;
    }

  syslog(LOG_INFO,
         "=== sg2000_eth TX hardware test ===\n"
         "  tx_desc[%u]=%p  tx_buf=%p  test_len=%d\n",
         idx, desc, priv->tx_buf[idx], test_len);

  /* STEP 1: Build a minimal broadcast ARP frame.
   * dst=ff:ff:ff:ff:ff:ff  src=our MAC  type=0x0806  payload=0xAA
   */

  memset(priv->tx_buf[idx], 0, test_len);
  memset(priv->tx_buf[idx], 0xff, 6);
  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);
  priv->tx_buf[idx][12] = 0x08;
  priv->tx_buf[idx][13] = 0x06;
  memset(priv->tx_buf[idx] + 14, 0xaa, test_len - 14);

  /* STEP 2: Snapshot hardware state before submission */

  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);

  syslog(LOG_INFO,
         "tx_test: BEFORE doorbell\n"
         "  desc des0=0x%08" PRIX32 " des2=0x%08" PRIX32 "\n"
         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
         " TX_FSM=%u\n",
         desc->des0, desc->des2, csr5_before, csr6,
         (csr5_before >> 20) & 0x7);

  /* STEP 3: Program TX descriptor.
   *   des2 = buffer physical address
   *   des1 = len | FS | LS | IC (preserve TER)
   *   des0 = OWN (hand to DMA)
   */

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
  desc->des1 = (uint32_t)test_len | TX_DESC_FS | TX_DESC_LS |
               TX_DESC_IC | (desc->des1 & TX_DESC_TER);
  desc->des0 = DESC_OWN;

  /* STEP 4: Flush D-cache to DDR.
   *   DMA reads from DDR, not from CPU cache.
   *   Without this, DMA sees stale descriptor values.
   */

  up_clean_dcache((uintptr_t)priv->tx_buf[idx],
                  (uintptr_t)priv->tx_buf[idx] + test_len);
  up_clean_dcache((uintptr_t)desc,
                  (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
  __asm__ volatile ("fence ow,ow" ::: "memory");

  syslog(LOG_INFO, "tx_test: D-cache flushed, ringing TX doorbell...\n");

  /* STEP 5: Ring TX doorbell */

  tx_doorbell(priv);

  /* STEP 6: Wait for TX completion.
   *   Poll until DMA clears OWN AND TI bit is set, or timeout.
   */

  timeout = 50000;

  while (--timeout > 0)
    {
      csr5_after = getreg32(priv->gmac_base + DMA_STATUS);

      if (!(desc->des0 & DESC_OWN) && (csr5_after & DMA_STATUS_TI))
        {
          break;
        }

      up_udelay(10);
    }

  syslog(LOG_INFO,
         "tx_test: waited %d us  timeout=%s\n"
         "  CSR5=0x%08" PRIX32 " TI=%s\n",
         (50000 - timeout) * 10,
         timeout > 0 ? "no" : "YES",
         csr5_after,
         (csr5_after & DMA_STATUS_TI) ? "SET" : "clear");

  /* STEP 7: Verify layer by layer */

  /* Layer 1: Did DMA fetch the descriptor?
   *   DMA sees OWN=1 → claims it → clears OWN when done.
   *   OWN still set → DMA never saw it (cache problem or DMA stopped).
   */

  if (desc->des0 & DESC_OWN)
    {
      syslog(LOG_ERR,
             "*** FAIL [L1]: OWN still set — DMA did NOT fetch "
             "descriptor!\n"
             "  DMA reads from DDR; descriptor stuck in D-cache.\n"
             "  CSR5=0x%08" PRIX32 " TX_FSM=%u\n",
             csr5_after, (csr5_after >> 20) & 0x7);
      ret = -ETIMEDOUT;
      goto out;
    }

  syslog(LOG_INFO, "  [L1 PASS] DMA fetched descriptor (OWN cleared)\n");

  /* Layer 2: Did DMA read the data correctly?
   *   Underflow = DMA couldn't read data fast enough (stale cache).
   *   Error Summary in des0 = any TX error occurred.
   */

  if (csr5_after & DMA_STATUS_UNF)
    {
      syslog(LOG_ERR,
             "*** FAIL [L2]: TX Underflow — DMA could not read "
             "buffer data!\n  CSR5=0x%08" PRIX32 "\n", csr5_after);
      ret = -EIO;
      goto out;
    }

  if (desc->des0 & TX_DESC_ES)
    {
      syslog(LOG_ERR,
             "*** FAIL [L2]: TX Error Summary in des0=0x%08"
             PRIX32 "\n", desc->des0);
      ret = -EIO;
      goto out;
    }

  syslog(LOG_INFO, "  [L2 PASS] No Underflow/Error — data read OK\n");

  /* Layer 3: Did TX Complete interrupt fire?
   *   IC bit was set in des1 → MAC should raise TI in CSR5.
   */

  if (!(csr5_after & DMA_STATUS_TI))
    {
      syslog(LOG_ERR,
             "*** FAIL [L3]: TI not set — TX Complete interrupt "
             "did NOT fire!\n  Check CSR7 / GMAC_INT_MASK.\n");
      ret = -EIO;
      goto out;
    }

  syslog(LOG_INFO, "  [L3 PASS] TX Complete interrupt (TI) fired\n");

  syslog(LOG_INFO,
         "=== TX TEST PASSED ===  total ~%d us\n",
         (50000 - timeout) * 10);

out:
  /* Advance tx_cur (mirror hw_transmit behavior) */

  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  /* Clear TI so it doesn't interfere with normal ISR */

  if (csr5_after & DMA_STATUS_TI)
    {
      putreg32(DMA_STATUS_TI, priv->gmac_base + DMA_STATUS);
    }

  return ret;
}

